#include "station/StationBlueprintLibrarySystem.h"

#include <fstream>
#include <iomanip>
#include <sstream>

namespace subspace {
namespace {
template<class T>bool Read(std::istringstream&in,T&v){return static_cast<bool>(in>>v);}bool ReadQuoted(std::istringstream&in,std::string&v){return static_cast<bool>(in>>std::quoted(v));}
}
std::string StationBlueprintLibrarySystem::CanonicalId(const StationBlueprintDocument&b){std::uint32_t h=2166136261u;auto mix=[&](const std::string&s){for(unsigned char c:s){h^=c;h*=16777619u;}};mix(b.name);mix(b.recipe.grammarId);for(const auto&m:b.recipe.modules)mix(m.moduleId);for(const auto&p:b.recipe.logicalPieceIds)mix(p);std::ostringstream o;o<<"station_bp_"<<std::hex<<h;return o.str();}
bool StationBlueprintLibrarySystem::Save(const StationBlueprintDocument&b,const std::string&path,std::string*error){std::ofstream f(path,std::ios::trunc);if(!f){if(error)*error="could not open station blueprint path";return false;}const std::string id=b.blueprintId.empty()?CanonicalId(b):b.blueprintId;f<<"SUBSPACE_STATION_BLUEPRINT_V1\n";f<<"META "<<std::quoted(id)<<' '<<std::quoted(b.name)<<' '<<std::quoted(b.author)<<' '<<b.revision<<"\n";f<<"RECIPE "<<std::quoted(b.recipe.identity)<<' '<<std::quoted(b.recipe.grammarId)<<' '<<static_cast<int>(b.recipe.archetype)<<' '<<b.recipe.seed<<"\n";f<<"DOCK "<<b.recipe.primaryDockLocal.x<<' '<<b.recipe.primaryDockLocal.y<<' '<<b.recipe.primaryDockLocal.z<<' '<<b.recipe.primaryDockDirection.x<<' '<<b.recipe.primaryDockDirection.y<<' '<<b.recipe.primaryDockDirection.z<<"\n";for(const auto&t:b.tags)f<<"TAG "<<std::quoted(t)<<"\n";for(std::size_t i=0;i<b.recipe.modules.size();++i){const auto&m=b.recipe.modules[i];const std::string piece=i<b.recipe.logicalPieceIds.size()?b.recipe.logicalPieceIds[i]:std::string{};const int role=i<b.recipe.logicalRoles.size()?static_cast<int>(b.recipe.logicalRoles[i]):0;f<<"MODULE "<<std::quoted(m.moduleId)<<' '<<std::quoted(piece)<<' '<<role<<' '<<m.x<<' '<<m.y<<' '<<m.z<<' '<<m.scaleX<<' '<<m.scaleY<<' '<<m.scaleZ<<' '<<m.yawDegrees<<' '<<m.pitchDegrees<<' '<<m.rollDegrees<<' '<<static_cast<int>(m.material)<<' '<<(m.mirrorX?1:0)<<' '<<(m.mirrorY?1:0)<<' '<<(m.mirrorZ?1:0)<<"\n";}for(const auto&a:b.recipe.attachments)f<<"ATTACH "<<a.parentModuleIndex<<' '<<a.childModuleIndex<<' '<<std::quoted(a.parentSocket)<<' '<<std::quoted(a.childSocket)<<' '<<a.measuredGap<<' '<<(a.certified?1:0)<<"\n";f<<"DNA "<<std::quoted(b.designDna.id)<<' '<<b.designDna.radiality<<' '<<b.designDna.symmetry<<' '<<b.designDna.structuralRatio<<"\n";if(!f.good()){if(error)*error="failed while writing station blueprint";return false;}return true;}
bool StationBlueprintLibrarySystem::Load(const std::string&path,StationBlueprintDocument&b,std::string*error){std::ifstream f(path);if(!f){if(error)*error="could not open station blueprint path";return false;}std::string line;if(!std::getline(f,line)||line!="SUBSPACE_STATION_BLUEPRINT_V1"){if(error)*error="unsupported station blueprint schema";return false;}b={};while(std::getline(f,line)){if(line.empty())continue;std::istringstream in(line);std::string kind;in>>kind;if(kind=="META"){if(!ReadQuoted(in,b.blueprintId)||!ReadQuoted(in,b.name)||!ReadQuoted(in,b.author)||!Read(in,b.revision)){if(error)*error="invalid META row";return false;}}else if(kind=="RECIPE"){int a=0;if(!ReadQuoted(in,b.recipe.identity)||!ReadQuoted(in,b.recipe.grammarId)||!Read(in,a)||!Read(in,b.recipe.seed)){if(error)*error="invalid RECIPE row";return false;}b.recipe.archetype=static_cast<StationArchetype>(a);}else if(kind=="DOCK"){if(!Read(in,b.recipe.primaryDockLocal.x)||!Read(in,b.recipe.primaryDockLocal.y)||!Read(in,b.recipe.primaryDockLocal.z)||!Read(in,b.recipe.primaryDockDirection.x)||!Read(in,b.recipe.primaryDockDirection.y)||!Read(in,b.recipe.primaryDockDirection.z)){if(error)*error="invalid DOCK row";return false;}b.recipe.usedDedicatedDock=true;}else if(kind=="TAG"){std::string t;if(!ReadQuoted(in,t)){if(error)*error="invalid TAG row";return false;}b.tags.push_back(t);}else if(kind=="MODULE"){VisualModulePlacement m;std::string piece;int role=0,material=0,mirror=0,mirrorY=0,mirrorZ=0;if(!ReadQuoted(in,m.moduleId)||!ReadQuoted(in,piece)||!Read(in,role)||!Read(in,m.x)||!Read(in,m.y)||!Read(in,m.z)||!Read(in,m.scaleX)||!Read(in,m.scaleY)||!Read(in,m.scaleZ)||!Read(in,m.yawDegrees)||!Read(in,m.pitchDegrees)||!Read(in,m.rollDegrees)||!Read(in,material)||!Read(in,mirror)){if(error)*error="invalid MODULE row";return false;}m.material=static_cast<SpaceMaterialKind>(material);m.mirrorX=mirror!=0;if(in>>mirrorY)m.mirrorY=mirrorY!=0;if(in>>mirrorZ)m.mirrorZ=mirrorZ!=0;b.recipe.modules.push_back(m);b.recipe.logicalPieceIds.push_back(piece);b.recipe.logicalRoles.push_back(static_cast<StationKitbashPieceRole>(role));}else if(kind=="ATTACH"){VisualAssemblyAttachment a;int cert=0;if(!Read(in,a.parentModuleIndex)||!Read(in,a.childModuleIndex)||!ReadQuoted(in,a.parentSocket)||!ReadQuoted(in,a.childSocket)||!Read(in,a.measuredGap)||!Read(in,cert)){if(error)*error="invalid ATTACH row";return false;}a.certified=cert!=0;b.recipe.attachments.push_back(a);}else if(kind=="DNA"){if(!ReadQuoted(in,b.designDna.id)||!Read(in,b.designDna.radiality)||!Read(in,b.designDna.symmetry)||!Read(in,b.designDna.structuralRatio)){if(error)*error="invalid DNA row";return false;}}}b.recipe.resolved=!b.recipe.modules.empty();b.recipe.connectedGraph=b.recipe.resolved&&b.recipe.attachments.size()+1==b.recipe.modules.size();b.designDna.archetype=b.recipe.archetype;b.designDna.grammarId=b.recipe.grammarId;b.designDna.moduleCount=static_cast<int>(b.recipe.modules.size());b.designDna.attachmentCount=static_cast<int>(b.recipe.attachments.size());if(b.name.empty())b.name="Untitled Station";return true;}
} // namespace subspace
